M(v3m, r"""
public static boolean oldOpen(@PKG@.TreeData d, int ci, int b, int n) {
  if (d == null || ci < 0 || ci >= @PKG@.TreeV3.NCV || n <= 1) return true;
  int sp = 0;
  int above = 0;
  int cap = 0;
  for (int u = @PKG@.TreeV3.TU0[ci]; u < @PKG@.TreeV3.TU0[ci] + @PKG@.TreeV3.TUN[ci]; u++) {
    if (@PKG@.TreeV3.UOB[u] != b) continue;
    int c = d.rk[u] * @PKG@.TreeV3.UCOST[u];
    sp = sp + c;
    if (@PKG@.TreeV3.UOR[u] == n - 1) { above = above + c; if (@PKG@.TreeV3.live(u)) cap = cap + @PKG@.TreeV3.UMAX[u] * @PKG@.TreeV3.UCOST[u]; }
  }
  int a = @PKG@.TreeCfg.CL_ABOVE;
  if (a > cap) a = cap;
  return sp >= @PKG@.TreeCfg.CL_STEP * (n - 1) && (a <= 0 || above >= a);
}""")
M(v3m, r"""
public static int pathRanks(@PKG@.TreeData d, int ci, int p) {
  int s = 0;
  for (int u = @PKG@.TreeV3.TU0[ci]; u < @PKG@.TreeV3.TU0[ci] + @PKG@.TreeV3.TUN[ci]; u++) if (@PKG@.TreeV3.UPATH[u] == p) s = s + d.rk[u];
  return s;
}""")
